def render(slug, title, description, body):
    url = f"{BASE}/{slug}/"
    article = slug.startswith("dergi/")
    structured = f'<script type="application/ld+json">{{"@context":"https://schema.org","@type":"{"Article" if article else "WebPage"}","headline":"{escape(title)}","url":"{url}","publisher":{{"@type":"Organization","name":"GuzelAI Medya","url":"{BASE}/"}}}}</script>'
    return f'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | GuzelAI</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{url}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{url}"><style>{STYLE}</style>{structured}</head><body><header><nav><a href="/">GuzelAI</a><a href="/#kombinler">Kombinler</a><a href="/#sosyal-paylasimlar">Instagram arşivi</a><a href="/hakkimizda/">Hakkımızda</a></nav></header><main><p class="eyebrow">{'GuzelAI rehberi' if article else 'GuzelAI Medya'}</p><h1>{escape(title)}</h1><p class="note">{escape(description)}</p>{body}</main><footer><nav><a href="/">Ana sayfa</a><a href="/iletisim/">İletişim</a><a href="/gizlilik-politikasi/">Gizlilik ve çerezler</a></nav></footer></body></html>'''

files = {f"{slug}/index.html": render(slug, *content) for slug, content in PAGES.items()}
files["robots.txt"] = f"User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n"
urls = [f"{BASE}/", *(f"{BASE}/{slug}/" for slug in PAGES)]
files["sitemap.xml"] = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + ''.join(f'<url><loc>{escape(url)}</loc></url>' for url in urls) + '</urlset>'
print(json.dumps(files, ensure_ascii=True))
